const tasks = [
  { id: 1, title: "Learn types", status: "todo" },
  { id: 2, title: "Build app", status: "in-progress" },
  { id: 3, title: "Write tests", status: "done" },
  { id: 4, title: "Review code", status: "todo", dueDate: "2026-10-10" }
];
const result = filterByStatus(tasks, "todo");
return result.length === 2 && result[0].id === 1 && result[1].id === 4;

const tasks = [
  { id: 1, title: "First", status: "todo" },
  { id: 2, title: "Second", status: "done" }
];
const result = filterByStatus(tasks, "in-progress");
return Array.isArray(result) && result.length === 0;

const tasks = [
  { id: 1, title: "First", status: "todo" },
  { id: 2, title: "Second", status: "todo" },
  { id: 3, title: "Third", status: "done" }
];
const result = countByStatus(tasks);
return result.todo === 2 && result["in-progress"] === 0 && result.done === 1 && Object.keys(result).length === 3;

const tasks = [
  { id: 1, title: "One", status: "in-progress" },
  { id: 2, title: "Two", status: "in-progress" },
  { id: 3, title: "Three", status: "done" },
  { id: 4, title: "Four", status: "todo" }
];
const result = countByStatus(tasks);
return result.todo === 1 && result["in-progress"] === 2 && result.done === 1;

const numbers = [10, 20, 30];
const names = ["Anna", "Peter"];
return firstOrNull(numbers) === 10 && firstOrNull(names) === "Anna";
